preConditionHook:
// Davey exit #11, statement for statement. ppratio is a PERSISTENT variable
// in the book (EL `Var: ppratio(0)`), overwritten by the three tier tests in
// sequence so the highest floor reached wins; it is deliberately not reset
// per bar. Its stale value never matters because the exit is gated on
// floor1, at which point the first assignment has just run. Division form
// and `>=` as in ProfitProtectorRatio; the nested if keeps the division
// behind the floor1 gate, so MaxPositionProfit is never 0 there.
if (el_ge(ctx.MaxPositionProfit(), floor1)) ppratio = ratio1;
if (el_ge(ctx.MaxPositionProfit(), floor2)) ppratio = ratio2;
if (el_ge(ctx.MaxPositionProfit(), floor3)) ppratio = ratio3;
ratioBelow = false;
if (el_ge(ctx.MaxPositionProfit(), floor1)) {
    if (el_lt(ctx.OpenPositionProfit() / ctx.MaxPositionProfit(), ppratio)) ratioBelow = true;
}
